      AND substr(p_digits,length(cc)+1) ~ ('^(?:'||pattern||')$')
  )
  SELECT CASE count(*) WHEN 0 THEN NULL WHEN 1 THEN min(region) ELSE 'ZZ' END FROM matched
$region$;
REVOKE ALL ON FUNCTION brand_phone_private.farouj_phone_region(text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION brand_phone_private.farouj_phone_region(text) TO service_role;

CREATE OR REPLACE FUNCTION brand_phone_private.normalize(p_cafe uuid,p_value text)
RETURNS text LANGUAGE plpgsql STABLE STRICT SECURITY INVOKER SET search_path='' AS $phone$
DECLARE digits text;
BEGIN
  IF p_cafe <> 'ec9b4415-b68e-4554-acbd-c918bd5cc2f2' THEN
    RETURN (SELECT brand_phone_private.normalize_country(c.phone_country,p_value,false) FROM public.cafes c WHERE c.id=p_cafe);
  END IF;
  IF length(p_value)>64 THEN RETURN NULL; END IF;
  digits:=translate(p_value,'٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','01234567890123456789');
  digits:=translate(digits,chr(1564)||chr(8203)||chr(8204)||chr(8205)||chr(8206)||chr(8207)||chr(8234)||chr(8235)||chr(8236)||chr(8237)||chr(8238)||chr(8288)||chr(8294)||chr(8295)||chr(8296)||chr(8297)||chr(65279),'');
  digits:=regexp_replace(digits,'[[:space:]()-]','','g');
  digits:=regexp_replace(digits,'^(?:[+]|00)','');
  IF brand_phone_private.farouj_phone_region(digits) IS NOT NULL THEN RETURN digits; END IF;
  RETURN brand_phone_private.normalize_country('AE',p_value,false);
END $phone$;
COMMIT;
